/* Not a correctness test: this times query processing against a real
 * gossmap, to get real numbers for CPU-budgeting constants.  Opt-in only,
 * since it needs a (large, private) gossip_store: set GOSSMAP_BENCH_FILE,
 * or drop one at gossip_store-<date> in the top-level directory. */
static const char *find_bench_file(void)
{
	const char *path = getenv("GOSSMAP_BENCH_FILE");
	if (path)
		return path;
	return "gossip_store-2026-08-17";
}

int main(int argc, char *argv[])
{
	const char *path;
	struct gossmap *gossmap;
	struct timemono start;
	struct short_channel_id *scids;
	size_t limit;
	u8 *msg;

	common_setup(argv[0]);
	chainparams = chainparams_for_network("bitcoin");

	path = find_bench_file();
	start = time_mono();
	gossmap = gossmap_load(tmpctx, path, NULL, NULL);
	if (!gossmap) {
		printf("SKIP: no gossmap at '%s' (set GOSSMAP_BENCH_FILE to enable timing)\n",
		       path);
		common_shutdown();
		return 0;
	}
	printf("Loaded %s: %zu msec\n", path,
	       (size_t)time_to_msec(timemono_between(time_mono(), start)));
	printf("  %zu nodes, %zu channels\n",
	       gossmap_num_nodes(gossmap), gossmap_num_chans(gossmap));

	/* Cold gather: everything, as a peer asking for the whole chain
	 * would trigger (independent of how narrow their range actually
	 * is: we still walk every channel). */
	start = time_mono();
	scids = gather_range_scids(tmpctx, gossmap, 0, UINT32_MAX);
	printf("gather_range_scids (cold, %zu scids): %"PRIu64" usec\n",
	       tal_count(scids),
	       time_to_usec(timemono_between(time_mono(), start)));

	/* Warm: repeat, as a peer sending repeated queries would trigger. */
	start = time_mono();
	for (size_t i = 0; i < 10; i++)
		tal_free(gather_range_scids(NULL, gossmap, 0, UINT32_MAX));
	u64 warm_usec = time_to_usec(timemono_between(time_mono(), start));
	printf("gather_range_scids (warm, x10): %"PRIu64" usec total, %"PRIu64" usec/call\n",
	       warm_usec, warm_usec / 10);

	/* One chunk's worth (what a single trickled reply actually costs),
	 * with both timestamps and checksums: the expensive per-scid work. */
	limit = max_entries(QUERY_ADD_TIMESTAMPS|QUERY_ADD_CHECKSUMS);
	if (limit > tal_count(scids))
		limit = tal_count(scids);
	start = time_mono();
	msg = make_reply_channel_range(tmpctx, gossmap, 0, UINT32_MAX,
				       scids, limit,
				       QUERY_ADD_TIMESTAMPS|QUERY_ADD_CHECKSUMS,
				       true);
	printf("make_reply_channel_range (1 chunk, %zu scids, tstamps+csums): %"PRIu64" usec (%zu bytes)\n",
	       limit,
	       time_to_usec(timemono_between(time_mono(), start)),
	       tal_bytelen(msg));

	/* The whole lot in one non-chunked call: what we used to do
	 * synchronously before trickling.  (Byte count is meaningless here:
	 * this deliberately exceeds max_entries(), which is the only thing
	 * that normally keeps encoded_short_ids under the wire format's
	 * u16 length field; production code never does this.) */
	start = time_mono();
	make_reply_channel_range(tmpctx, gossmap, 0, UINT32_MAX,
				 scids, tal_count(scids),
				 QUERY_ADD_TIMESTAMPS|QUERY_ADD_CHECKSUMS,
				 true);
	printf("make_reply_channel_range (all %zu scids at once, tstamps+csums): %"PRIu64" usec\n",
	       tal_count(scids),
	       time_to_usec(timemono_between(time_mono(), start)));

	/* Same, but scids only (no lookups at all): isolates the cost of
	 * the gossmap_find_chan + checksum/timestamp lookups above. */
	start = time_mono();
	make_reply_channel_range(tmpctx, gossmap, 0, UINT32_MAX,
				 scids, tal_count(scids), 0, true);
	printf("make_reply_channel_range (all %zu scids at once, no tstamps/csums): %"PRIu64" usec\n",
	       tal_count(scids),
	       time_to_usec(timemono_between(time_mono(), start)));

	common_shutdown();
	return 0;
}
